<?php
/**
 * includes/pdf_report.php
 * Improvement 4: PDF export. Thin FPDF subclass shared by every report's
 * *_pdf.php export endpoint, so all four reports look consistent (same
 * header with the municipality name + report title + filter summary +
 * "generated by / generated at" line, same footer with page numbers).
 *
 * Uses the vendored lib/fpdf.php (no Composer) - see lib/FPDF_LICENSE.txt.
 */
require_once __DIR__ . '/../lib/fpdf.php';

class MunicipalReportPdf extends FPDF
{
    private string $reportTitle;
    private string $filterSummary;
    private string $generatedBy;

    public function __construct(string $reportTitle, string $filterSummary, string $generatedBy)
    {
        parent::__construct('L', 'mm', 'A4'); // Landscape - report tables are wide.
        $this->reportTitle = $reportTitle;
        $this->filterSummary = $filterSummary;
        $this->generatedBy = $generatedBy;
        $this->SetMargins(12, 12, 12);
        $this->SetAutoPageBreak(true, 16);
        $this->AddPage();
    }

    public function Header(): void
    {
        $this->SetFont('Arial', 'B', 15);
        $this->Cell(0, 7, 'Beitbridge Municipality', 0, 1, 'L');
        $this->SetFont('Arial', 'B', 12);
        $this->Cell(0, 7, $this->reportTitle, 0, 1, 'L');
        $this->SetFont('Arial', '', 9);
        $this->SetTextColor(90, 98, 110);
        if ($this->filterSummary !== '') {
            $this->Cell(0, 5, $this->filterSummary, 0, 1, 'L');
        }
        $this->Cell(0, 5, 'Generated by ' . $this->generatedBy . ' on ' . date('d M Y H:i'), 0, 1, 'L');
        $this->SetTextColor(0, 0, 0);
        $this->Ln(3);
    }

    public function Footer(): void
    {
        $this->SetY(-14);
        $this->SetFont('Arial', 'I', 8);
        $this->SetTextColor(120, 120, 120);
        $this->Cell(0, 8, 'Page ' . $this->PageNo() . ' of {nb}', 0, 0, 'C');
    }

    /**
     * Draws a table with a shaded header row and auto-sized columns.
     * $columns = ['Header' => widthMm, ...]; $rows = [['col1val', 'col2val', ...], ...]
     */
    public function table(array $columns, array $rows): void
    {
        $this->SetFont('Arial', 'B', 9);
        $this->SetFillColor(44, 120, 115); // teal, matches the app's --teal
        $this->SetTextColor(255, 255, 255);
        foreach ($columns as $label => $width) {
            $this->Cell($width, 8, $label, 1, 0, 'L', true);
        }
        $this->Ln();

        $this->SetFont('Arial', '', 9);
        $this->SetTextColor(30, 34, 42);
        $fill = false;
        foreach ($rows as $row) {
            $this->SetFillColor(244, 246, 249);
            $i = 0;
            foreach ($columns as $width) {
                $text = (string) ($row[$i] ?? '');
                $this->Cell($width, 7, $this->clean($text), 1, 0, 'L', $fill);
                $i++;
            }
            $this->Ln();
            $fill = !$fill;
        }

        if (!$rows) {
            $this->SetFont('Arial', 'I', 9);
            $this->Cell(array_sum($columns), 8, 'No matching records.', 1, 1, 'C');
        }
    }

    // FPDF's built-in fonts only support Windows-1252, not UTF-8 - the
    // app's data (names, descriptions) is stored as UTF-8 throughout, so
    // this converts on the way into the PDF only, nowhere else.
    private function clean(string $text): string
    {
        return iconv('UTF-8', 'windows-1252//TRANSLIT//IGNORE', $text) ?: $text;
    }
}
